/** Client-safe Quran types. Data lives in /data/quran (generated by scripts/fetch-quran-data.mjs). */
export interface ChapterLite {
  id: number
  slug: string
  nameSimple: string
  nameArabic: string
  /** Bengali translated meaning of the name (from Quran.com) */
  nameBn: string | null
  meaning: string
  revelationPlace: 'makkah' | 'madinah' | string
  versesCount: number
  pages: [number, number] | number[]
}

export interface Chapter extends ChapterLite {
  nameComplex: string
  revelationOrder: number
  bismillahPre: boolean
  summaryEn: string | null
  summaryBn: string | null
}

/** Compact verse record (keys kept short to keep the corpus small). */
export interface Verse {
  /** verse number in surah */ n: number
  /** verse key "2:255" */ k: string
  /** Uthmani script */ ar: string
  /** simple (imlaei) Arabic without diacritics – for search */ sim: string
  /** Saheeh International */ en: string
  /** M.A.S. Abdel Haleem */ enH: string
  /** Bengali – Taisirul Quran */ bn: string
  /** English transliteration */ tl: string
  /** juz */ j: number
  /** mushaf page (Madani 604) */ p: number
  /** hizb */ h: number
  /** ruku */ r: number
  /** sajdah ayah */ s: 0 | 1
}

export interface JuzInfo {
  juz: number
  /** { "1": "1-7", "2": "1-141" } */
  map: Record<string, string>
  count: number
}
